/* ZhiXu: browser-local learning app. No external API or credentials required. */
(() => {
'use strict';
const DB=window.QUESTION_BANK,Q=DB.questions,TOPICS=Object.keys(DB.notes),$=s=>document.querySelector(s);
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={home:'M3 10 12 3l9 7v11h-6v-7H9v7H3Z',random:'M3 5h3c5 0 7 14 12 14h3m-4-4 4 4-4 4M3 19h3c2 0 4-3 6-7s4-7 6-7h3m-4-4 4 4-4 4',target:'M21 12a9 9 0 1 1-9-9m0 4a5 5 0 1 0 5 5m-5 0 9-9m-5 0h5v5',exam:'M7 3h10v3H7ZM6 5H4v17h16V5h-2M8 11h8M8 15h8M8 19h5',book:'M12 5C8 2 3 3 3 3v16s5-1 9 2c4-3 9-2 9-2V3s-5-1-9 2Zm0 0v16',light:'M9 19h6m-5 3h4m-6-7a7 7 0 1 1 8 0c-1 1-1 2-1 2H9s0-1-1-2Z',export:'M12 3v12m-4-4 4 4 4-4M4 15v6h16v-6',grid:'M3 3h7v7H3Zm11 0h7v7h-7ZM3 14h7v7H3Zm11 0h7v7h-7Z',arrow:'M4 12h16m-6-6 6 6-6 6',check:'m5 12 4 4L20 5',clock:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18Zm0 4v5l4 2',flag:'M5 22V3h14l-3 5 3 5H5',close:'m6 6 12 12M6 18 18 6',shield:'m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6Zm-4 9 3 3 5-6',chart:'M4 3v18h17M8 17v-5m5 5V8m5 9V5',file:'M5 3h10l4 4v14H5Zm10 0v5h4M8 12h8m-8 4h6',user:'M12 3a4 4 0 1 0 0 8 4 4 0 0 0 0-8ZM4 22v-4a8 6 0 0 1 16 0v4',chevron:'m9 5 7 7-7 7'};
const icon=(n,size=20)=>`<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${icons[n]||icons.file}"/></svg>`;
function read(store,key,fallback){try{return JSON.parse(store.getItem(key))??fallback}catch{return fallback}}
function write(store,key,val){try{store.setItem(key,JSON.stringify(val))}catch{toast('浏览器存储不可用，本次学习仅在当前页面保存。')}}
let history=read(localStorage,'zhixu-history',[]),wrong=read(sessionStorage,'zhixu-wrong',[]),session=read(sessionStorage,'zhixu-session',null),report=read(sessionStorage,'zhixu-report',null);
if(session&&!session.ids.every(id=>Q.some(q=>q.id===id)))session=null;
let page='home',noteTopic=TOPICS[0],exportSet=[],exportTeacher=false,exportTitle='广东高中信息技术学考练习卷',reviewId=null,filters={topic:'全部',type:'全部',source:'全部',search:''};
const qBy=id=>Q.find(q=>q.id===id),paper=id=>DB.papers.find(p=>p.id===id),typeNames={single:'单选题',multi:'多选题',judge:'判断题',fill:'程序 / 编码填空',subjective:'综合应用题'};
const sourceText=q=>q.kind==='true'?'【历年学考真题】':'【模拟题，对标真题考点】';
const sourceName=q=>q.paper==='mock'?'知序 · 对标模拟':paper(q.paper)?.short;
const badge=q=>`<span class="badge ${q.kind==='true'?'':'orange'}">${sourceText(q)}</span>`;
const btn=(label,act,extra='',cls='')=>`<button class="button ${cls}" data-act="${act}" ${extra}>${label}</button>`;
const answered=a=>Array.isArray(a)?a.length>0:String(a??'').trim().length>0;
const norm=a=>String(a??'').normalize('NFKC').trim().replace(/\s+/g,'');
function evaluate(q,a){
 if(q.manual)return {earned:null,max:q.points,status:'待评阅'};
 if(!answered(a))return {earned:0,max:q.points,status:'未作答'};
 let ok=false,earned=0;
 if(q.type==='multi'){
  const selected=[...new Set(Array.isArray(a)?a:String(a).toUpperCase().split(''))].sort();
  const target=q.answer.split('').sort();
  ok=selected.join('')===target.join('');
  earned=ok?q.points:(selected.length&&selected.every(v=>target.includes(v))?(q.partial||0):0);
 }else{ok=(q.accept||[q.answer]).some(v=>norm(v)===norm(a));earned=ok?q.points:0}
 return {earned,max:q.points,status:ok?'正确':earned?'部分正确':'错误'};
}
function selectQuestions({topic='全部',type='全部',source='priority',count=10}={}){
 let pool=Q.filter(q=>!q.manual&&(topic==='全部'||q.topic===topic)&&(type==='全部'||q.type===type));
 if(source==='true')pool=pool.filter(q=>q.kind==='true');if(source==='mock')pool=pool.filter(q=>q.kind!=='true');
 const shuffled=shuffle(pool);
 if(source==='priority')shuffled.sort((a,b)=>(a.kind==='true'?0:1)-(b.kind==='true'?0:1));
 return shuffled.slice(0,count);
}
function shuffle(items){const arr=[...items];for(let i=arr.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[arr[i],arr[j]]=[arr[j],arr[i]]}return arr}
function makeExam(p,group){return Q.filter(q=>q.paper===p&&(!q.group||q.group===group))}
function saveSession(){write(sessionStorage,'zhixu-session',session)}
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(toast.t);toast.t=setTimeout(()=>$('#toast').classList.remove('show'),3200)}
function modal(title,html){$('#modal').innerHTML=`<button class="dialog-close" data-act="close" aria-label="关闭对话框">${icon('close',18)}</button><h2 id="modal-title">${title}</h2>${html}`;$('#modal').showModal()}
function close(){$('#modal').close()}
const navItems=[['home','home','学习中心'],['random','random','随机刷题'],['special','target','专项刷题'],['exam','exam','全真模考'],['mistakes','book','临时错题本'],['explain','light','真题精讲'],['notes','file','考点速记'],['export','export','组卷导出'],['library','grid','题库与来源']];
function renderNav(){
 $('#sidebar').innerHTML=`<div class="brand"><span class="brand-mark">${icon('book',24)}</span><div><strong>知序</strong><small>ZHIXU · 学考题库</small></div></div><div class="nav-label">学习空间</div><nav class="nav">${navItems.slice(0,6).map(navButton).join('')}</nav><div class="nav-label">学习工具</div><nav class="nav">${navItems.slice(6).map(navButton).join('')}</nav><div class="sidebar-bottom"><div class="scope-card"><strong>${icon('shield',15)} 为广东学考而准备</strong>信息技术 · 合格性考试<br>从真题出发，逐个掌握考点</div><div class="profile"><div class="profile-icon">${icon('user',18)}</div><div>本地学习空间<small>无需注册 · 学习记录保存在本机</small></div></div></div>`;
}
function navButton([id,i,t]){return `<button data-act="nav" data-page="${id}" class="${page===id?'active':''}" ${page===id?'aria-current="page"':''}>${icon(i,19)}<span>${t}</span>${id==='mistakes'?`<span class="count">${wrong.length}</span>`:''}</button>`}
function go(next){if(page===next&&next!=='practice')return;location.hash=next;page=next;render();window.scrollTo(0,0)}
function pageHead(eyebrow,title,sub,right=''){return `<div class="page-head"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p class="sub">${sub}</p></div>${right}</div>`}
function render(){
 page=location.hash.slice(1)||page;const match=navItems.find(x=>x[0]===page);
 $('#breadcrumb').innerHTML=`学习中心 <span>/</span> ${match?.[2]||(page==='practice'?'正在作答':'得分报告')}`;
 renderNav();
 const views={home:homePage,random:randomPage,special:specialPage,exam:examPage,mistakes:mistakePage,explain:libraryPage,library:libraryPage,notes:notesPage,export:exportPage,practice:practicePage,report:reportPage};
 $('#main').innerHTML=(views[page]||homePage)();
 $('#sidebar').classList.remove('open');
 if(page==='practice')updateTimer();
}
function resumeBanner(){return session&&!session.finished?`<div class="resume"><span>${icon('clock',16)} 还有一份${session.mode==='exam'?'模考':'练习'}正在进行，已自动保存作答。</span>${btn('继续作答','nav','data-page="practice"','small')}</div>`:''}
function stats(){const total=history.length,correct=history.filter(h=>h.ratio===1).length,unique=new Set(history.map(h=>h.id)).size;return {total,correct,unique,accuracy:total?Math.round(correct/total*100):0}}
function homePage(){const st=stats();return pageHead('YOUR LEARNING SPACE','把每一个考点，学扎实。','广东高中信息技术学考，一道题、一个知识点，稳步向前。',`<span class="date-pill">${new Date().toLocaleDateString('zh-CN',{month:'long',day:'numeric',weekday:'long',timeZone:'Asia/Shanghai'})}</span>`)+resumeBanner()+`
 <section class="hero"><div><div class="eyebrow">FOCUS ON WHAT MATTERS · 聚焦学考</div><h2>从一道真题开始，<br>离合格更近一步。</h2><p>历年真题优先，八大考点逐一突破。先独立作答，再看答案与精讲，让每次练习都有收获。</p><div class="button-row">${btn('开始随机刷题 '+icon('arrow',16),'quick','','primary')}${btn('选择专项练习','nav','data-page="special"','text')}</div></div><svg class="hero-art" viewBox="0 0 230 210" aria-hidden="true"><path d="M32 172h168" stroke="#bdceb5"/><path d="M58 171v-45h43v45m-10 0V95h44v76m-10 0V61h43v110" fill="#d2e1c8" stroke="#a5b89c" stroke-width="1.5"/><path d="M47 112c24-3 33-29 51-30s26 5 40-21 36-25 47-28" fill="none" stroke="#608866" stroke-width="2" stroke-dasharray="4 5"/><circle cx="183" cy="33" r="13" fill="#f6faf1" stroke="#608866"/><path d="m177 33 4 4 8-9" fill="none" stroke="#4c7754" stroke-width="2"/><path d="M143 164q-8-37 16-52 11 28-16 52Z" fill="#87a785"/><path d="M144 164q4-25 25-24-3 22-25 24Z" fill="#b4c6a4"/><path d="m144 164 5-23" stroke="#628a63"/><rect x="38" y="142" width="29" height="29" rx="7" fill="#fafbf4" stroke="#adc1a0"/><path d="m45 157 5 5 10-13" fill="none" stroke="#608866" stroke-width="2"/><text x="116" y="197" text-anchor="middle" font-family="Consolas" font-size="8" letter-spacing="3" fill="#5b7a60">GROW WITH PRACTICE</text></svg></section>
 <section class="stats" aria-label="学习统计">${stat('题库小题',Q.length,'道','book')}${stat('已练习',st.unique,'道','check')}${stat('练习正确率',st.total?st.accuracy+'%':'—',st.total?'':'开始后记录','chart')}${stat('临时错题',wrong.length,'道待巩固','flag')}</section>
 <div class="dashboard-grid"><div><div class="section-title"><h2>选一种方式，进入学习</h2><span class="small-note">每次进步，从现在开始</span></div><div class="mode-grid">${mode('random','random','随机刷题','打破顺序，真题优先，随时练一组。','')}${mode('special','target','专项突破','按知识点练习，补上薄弱的那一环。','blue')}${mode('exam','exam','全真模考','按原卷结构作答，交卷后查看得分。','amber')}${mode('mistakes','book','错题再练','回到做错的地方，直到真正学会。','rose')}</div>
 <section class="paper-list"><div class="section-title"><h2>真题与原卷练习</h2>${btn('查看全部 '+icon('chevron',12),'nav','data-page="exam"','text small')}</div>${DB.papers.map(p=>`<div class="paper-row"><span class="paper-year">${p.id==='ft2425'?'2024<br>2025':'2023<br>'+ (p.id==='sz2303'?'03':'12')}</span><div><h3>${p.title}</h3><p>${p.kind==='true'?'历年真题':'区级模拟'} · ${p.max}分 · 综合题二选一</p></div>${btn('去模考','nav','data-page="exam"','small')}</div>`).join('')}</section></div>
 <aside class="panel"><div class="section-title"><h2>八大考点</h2><span class="small-note">已练 / 题量</span></div>${TOPICS.map(t=>{const qs=Q.filter(q=>q.topic===t),done=new Set(history.filter(h=>qBy(h.id)?.topic===t).map(h=>h.id)).size;return `<button class="topic-row" data-act="topic" data-topic="${t}"><span>${t.replace('算法Python基础','算法与 Python')}<small>${done} / ${qs.length}</small></span><div class="track"><i style="width:${done/qs.length*100}%"></i></div></button>`}).join('')}<div class="callout info" style="margin-bottom:0">学习小建议<br>先做一组真题，发现薄弱点，再进入专项练习。</div></aside></div>
 <div class="welcome-strip"><strong>你好，高中信息技术学考题库系统已就绪✅</strong><br>支持：随机刷题｜专项刷题｜全真模考｜错题本｜真题精讲｜考点速记｜组卷导出。</div>`}
function stat(label,n,unit,i){return `<div class="stat"><div><div class="stat-label">${label}</div><div class="stat-number">${n}<small>${unit}</small></div></div><span class="stat-icon">${icon(i,18)}</span></div>`}
function mode(p,i,t,desc,c){return `<button class="mode" data-act="nav" data-page="${p}"><span class="tile-icon ${c}">${icon(i,21)}</span><div><h3>${t}</h3><p>${desc}</p></div><span class="arrow">${icon('arrow',16)}</span></button>`}
function configHtml(topic='全部'){return `<form id="practice-form" class="panel config"><div class="grid-2"><div class="field"><label for="practice-topic">知识范围</label><select id="practice-topic" name="topic"><option>全部</option>${TOPICS.map(t=>`<option ${t===topic?'selected':''}>${t}</option>`).join('')}</select></div><div class="field"><label for="practice-type">题型</label><select id="practice-type" name="type"><option value="全部">全部题型</option>${Object.entries(typeNames).filter(([t])=>t!=='subjective').map(([t,n])=>`<option value="${t}">${n}</option>`).join('')}</select></div><div class="field"><label for="practice-source">题目来源</label><select id="practice-source" name="source"><option value="priority">历年真题优先</option><option value="true">只做历年真题</option><option value="mock">区级卷与模拟题</option><option value="all">全部来源随机混合</option></select></div><div class="field"><label for="practice-count">本次题数</label><select id="practice-count" name="count"><option value="5">5题 · 轻量热身</option><option value="10" selected>10题 · 日常练习</option><option value="20">20题 · 集中巩固</option></select></div></div><div class="callout info">每次呈现一道题。选择或填写答案后点击“提交答案”，再显示答案、考点、解析、易错提醒。开放问答与歧义题可在原卷模考中作答并人工评阅。</div><button class="button primary" type="submit">开始本次练习 ${icon('arrow',16)}</button></form>`}
function randomPage(){return pageHead('PRACTICE AT YOUR PACE','随机刷题','给自己几分钟，做一组有收获的练习。')+resumeBanner()+configHtml()}
function specialPage(){return pageHead('ONE TOPIC AT A TIME','专项突破，逐个掌握。','选择一个知识点，以原卷难度练习。')+`<div class="grid-3">${TOPICS.map((t,i)=>`<article class="topic-card"><span class="badge gray">${String(i+1).padStart(2,'0')} / KNOWLEDGE</span><h3>${t}</h3><p>${DB.notes[t].headline}<br>共 ${Q.filter(q=>q.topic===t).length} 道小题</p>${btn('开始专项 '+icon('arrow',14),'topic',`data-topic="${t}"`,'text')}</article>`).join('')}</div>`}
function examPage(){return pageHead('REAL EXAM EXPERIENCE','给自己一次完整的检验。','60分钟，保留原卷结构。作答时不显示答案，点击“交卷”后统一批改。')+resumeBanner()+`<div class="grid-3">${DB.papers.map(p=>`<article class="panel exam-card"><span class="badge ${p.kind==='true'?'':'orange'}">${p.kind==='true'?'历年学考真题':'区级模拟测试卷'}</span><h2>${p.title}</h2><div class="exam-meta"><span>${icon('clock',15)} 60分钟</span><span>满分 ${p.max}分</span></div><p>${p.note}</p><div class="field"><label for="group-${p.id}">综合应用题（二选一）</label><select id="group-${p.id}"><option value="26">${p.id==='sz2303'?'气象信息系统':p.id==='sz2312'?'红树林观鸟 · 程序补全':'闰年判断 · 程序填空'}</option><option value="27">${p.id==='sz2303'?'餐厅优惠 · 程序补全':p.id==='sz2312'?'亚运科技 · 信息系统':'家庭网络 · 含9分人工评阅'}</option></select></div>${btn('开始模考 '+icon('arrow',15),'start-exam',`data-paper="${p.id}"`,'primary')}</article>`).join('')}</div><div class="callout info">计时结束会锁定作答，仍需你点击“交卷”才批改。刷新页面可恢复本标签页的作答。2023年3月卷缺第15题，按现有题目97分出分，并单独显示正确率，不虚补真题。</div>`}
function beginSession(qs,mode='practice',title='随机练习'){
 if(!qs.length){toast('当前筛选没有可练题目，请调整条件。');return}
 const start=()=>{session={ids:qs.map(q=>q.id),answers:{},graded:{},index:0,mode,title,started:Date.now(),deadline:mode==='exam'?Date.now()+3600000:null,flags:[],finished:false};saveSession();go('practice');if(page==='practice')render()};
 if(session&&!session.finished)modal('已有一份未完成的作答',`<p>开始新练习会替换本标签页当前作答。已记录的临时错题会保留。</p><div class="button-row">${btn('继续原作答','resume','','primary')}${btn('替换并开始','replace-session')}</div>`),pendingStart=start;else start();
}
let pendingStart=null;
function currentQ(){return session?qBy(session.ids[session.index]):null}
function answerLabel(q,a){if(!answered(a))return '未作答';if(['fill','subjective'].includes(q.type))return String(a);const arr=Array.isArray(a)?a:[a];return arr.map(c=>`${c}．${q.options[c.charCodeAt(0)-65]||c}`).join('；')}
function correctLabel(q){return q.type==='multi'?answerLabel(q,q.answer.split('')):answerLabel(q,q.answer)}
function diagram(){return `<div class="flowchart" role="img" aria-label="开始，输入x，判断x大于0；是则输出正数，否则输出非正数，然后结束"><span class="node end">开始</span>↓<span class="node">输入 x</span>↓<div class="branch"><span>否 → 输出“非正数”</span><span class="diamond">x &gt; 0 ?</span><span>是 → 输出“正数”</span></div>↓<span class="node end">结束</span></div>`}
function questionBody(q,a,locked,showResult=false){
 const result=showResult?evaluate(q,a):null;
 return `${q.context?`<div class="context">${esc(q.context)}</div>`:''}${q.code?`<pre class="code"><code>${esc(q.code)}</code></pre>`:''}<h2 class="question-stem">${esc(q.stem)}</h2>${q.reviewNote?`<div class="callout">${esc(q.reviewNote)}</div>`:''}${q.image?`<img class="question-image" src="${q.imageData||q.image}" alt="本题原卷图示：${esc(q.stem)}">`:''}${q.diagram?diagram():''}
 ${q.options.length?`<div role="group" aria-label="作答选项">${q.options.map((v,i)=>{const c=String.fromCharCode(65+i),selected=Array.isArray(a)?a.includes(c):a===c,correct=showResult&&!q.manual&&(q.type==='multi'?q.answer.includes(c):(q.accept||[q.answer]).includes(c));return `<button class="option ${q.type==='multi'?'multi':''} ${selected?'selected':''} ${correct?'correct':''} ${showResult&&selected&&!correct&&!q.manual?'wrong':''}" data-act="answer" data-value="${c}" aria-pressed="${selected}" ${locked?'disabled':''}><span class="letter">${c}</span><span class="option-text">${esc(v)}</span></button>`}).join('')}</div>`:`<label class="field-label" for="answer-input">${q.type==='subjective'?'写下你的思路与答案':'填写你的答案'}</label>${q.type==='subjective'?`<textarea id="answer-input" class="answer-field" ${locked?'disabled':''}>${esc(a||'')}</textarea>`:`<input id="answer-input" class="answer-field" value="${esc(a||'')}" autocomplete="off" spellcheck="false" ${locked?'disabled':''}>`}`}`;
}
function analysis(q,a){const r=evaluate(q,a);return `<section class="analysis ${r.status==='正确'?'':'bad'}" id="analysis"><h3>${icon(r.status==='正确'?'check':'light',18)} ${r.earned===null?'等待人工评阅':r.status==='正确'?'回答正确，继续保持。':r.earned?'部分正确，再检查遗漏。':'再想一想，巩固这个考点。'} <span style="margin-left:auto;font-size:12px">${r.earned===null?'待评阅':r.earned+' / '+r.max+'分'}</span></h3><dl><dt>答案</dt><dd>${esc(q.manual?'参考：'+correctLabel(q):correctLabel(q))}${q.accept?'（原稿重复选项B、D均认可）':''}<br><small>你的作答：${esc(answerLabel(q,a))}</small></dd><dt>考点</dt><dd>${q.topic}</dd><dt>解析</dt><dd>${esc(q.explanation)}</dd><dt>易错提醒</dt><dd>${esc(q.pitfall)}</dd></dl><p class="small-note" style="margin:15px 0 0">${q.answerSource} · ${sourceName(q)} · 原题 ${q.number}</p></section>`}
function practicePage(){
 if(!session)return pageHead('READY WHEN YOU ARE','还没有正在进行的练习','选择一种方式开始吧。')+btn('去随机刷题','nav','data-page="random"','primary');
 if(session.finished)return reportPage();
 const q=currentQ(),a=session.answers[q.id],isExam=session.mode==='exam',graded=!!session.graded[q.id],expired=isExam&&Date.now()>=session.deadline,done=Object.values(session.answers).filter(answered).length;
 return pageHead(isExam?'EXAM IN PROGRESS':'FOCUSED PRACTICE',session.title,isExam?'先完成作答，再点击“交卷”查看成绩和解析。':'一次一道，认真思考。提交本题后显示精讲。',btn('保存并返回','nav','data-page="home"'))+`
 <div class="practice-layout"><article class="question-card"><div class="question-top"><div class="badges">${badge(q)}<span class="badge gray">${typeNames[q.type]}</span><span class="badge gray">${q.points}分</span></div><span class="small-note">第 ${session.index+1} / ${session.ids.length} 题</span></div><div class="small-note">${sourceName(q)} · 原题 ${q.number} · ${q.topic}</div>
 ${questionBody(q,a,isExam?expired:graded,graded&&!isExam)}
 ${graded&&!isExam?analysis(q,a):''}
 <div class="answer-controls"><span class="hint">${q.type==='multi'?'多选题可选多个选项':q.options.length?'支持键盘 A—D 选择':'按Python语法填写，大小写敏感'}</span><div class="button-row">${isExam?btn('上一题','prev',session.index===0?'disabled':''):''}${isExam?btn(session.index===session.ids.length-1?'交卷':'保存，下一题',session.index===session.ids.length-1?'submit-exam':'next','','primary'):graded?btn(session.index===session.ids.length-1?'完成练习，查看得分':'下一题 '+icon('arrow',15),'next','','primary'):btn('提交答案','grade',!answered(a)?'disabled':'','primary')}</div></div></article>
 <aside class="practice-aside"><div class="panel">${isExam?`<div class="progress-title">剩余作答时间</div><div id="timer" class="timer"></div><p id="timer-note" class="small-note">计时结束后，请手动交卷。</p><hr style="border:0;border-top:1px solid var(--line);margin:18px 0">`:''}<div class="progress-title">${isExam?'作答进度':'本次练习'}</div><div class="progress-number">${isExam?done:Object.keys(session.graded).length}<small> / ${session.ids.length} 题</small></div><div class="track"><i style="width:${(isExam?done:Object.keys(session.graded).length)/session.ids.length*100}%"></i></div><div class="q-grid">${session.ids.map((id,i)=>`<button data-act="jump" data-index="${i}" class="${i===session.index?'current':''} ${answered(session.answers[id])?'done':''} ${session.flags.includes(id)?'flagged':''}" aria-label="第${i+1}题${answered(session.answers[id])?'已作答':'未作答'}" ${!isExam&&i>session.index&&!session.graded[session.ids[i-1]]?'disabled':''}>${i+1}</button>`).join('')}</div><div class="legend"><span>深绿：当前</span><span>浅绿：已答</span><span>黄线：标记</span></div>${btn((session.flags.includes(q.id)?'取消标记':'标记稍后检查')+' '+icon('flag',14),'flag','','text small')}${isExam?`<div style="margin-top:14px">${btn('交卷并查看成绩','submit-exam','','primary')}</div>`:''}</div><div class="panel"><h3 style="font-size:13px">${icon('light',16)} 学习约定</h3><p class="small-note">${isExam?'答卷期间隐藏答案和解析。可以回看和修改作答，交卷后统一出分。':'先独立完成，再对照四步精讲。错题会自动进入本标签页的临时错题本。'}</p><span class="badge gray">${q.kind==='true'?'真题优先':'对标原卷难度'}</span></div></aside></div>`;
}
function updateTimer(){if(!session||session.mode!=='exam'||session.finished||page!=='practice')return;const left=Math.max(0,Math.ceil((session.deadline-Date.now())/1000)),el=$('#timer');if(el){el.textContent=`${String(Math.floor(left/60)).padStart(2,'0')}:${String(left%60).padStart(2,'0')}`;el.classList.toggle('expired',left===0)}if(left===0&&$('#timer-note')){$('#timer-note').textContent='时间已到，已锁定作答。请点击交卷。';$('#main').querySelectorAll('.option,.answer-field').forEach(x=>x.disabled=true)}}
setInterval(updateTimer,1000);
function record(q,a){if(q.manual)return;const r=evaluate(q,a);history.push({id:q.id,at:Date.now(),ratio:r.earned/q.points});history=history.slice(-5000);write(localStorage,'zhixu-history',history);if(r.earned<q.points&&!wrong.includes(q.id)){wrong.push(q.id);write(sessionStorage,'zhixu-wrong',wrong)}}
function finish(){if(!session||session.finished)return;const ids=session.ids,results=ids.map(id=>{const q=qBy(id),a=session.answers[id];if(session.mode==='exam')record(q,a);return {id,answer:a??'',...evaluate(q,a)}});report={title:session.title,mode:session.mode,results,finishedAt:Date.now(),seconds:Math.round((Date.now()-session.started)/1000),manualScores:{}};session.finished=true;saveSession();write(sessionStorage,'zhixu-report',report);reviewId=null;go('report');render()}
function submitExam(){const missing=session.ids.filter(id=>!answered(session.answers[id])).length;modal('确认交卷',`<p>本卷共 ${session.ids.length} 道小题，已作答 ${session.ids.length-missing} 道。${missing?`还有 <strong>${missing}</strong> 道未作答，将按0分计入。`:''}</p><p>交卷后统一显示得分报告和解析，不能修改本次作答。</p><div class="button-row">${btn('返回检查','close')}${btn('交卷','confirm-exam','','primary')}</div>`)}
function reportPage(){if(!report)return pageHead('LEARNING REPORT','还没有得分报告','完成一组练习或交卷后，报告就会出现在这里。')+btn('开始练习','nav','data-page="random"','primary');
 const total=report.results.reduce((s,r)=>s+r.max,0),raw=report.results.reduce((s,r)=>s+(r.earned??Number(report.manualScores[r.id]||0)),0),pending=report.results.filter(r=>r.earned===null&&report.manualScores[r.id]===undefined),pendingMax=pending.reduce((s,r)=>s+r.max,0),pct=Math.round(raw/total*100),correct=report.results.filter(r=>r.earned===r.max).length;
 const topicStats=TOPICS.map(t=>{const rr=report.results.filter(r=>qBy(r.id).topic===t),max=rr.reduce((s,r)=>s+r.max,0),score=rr.reduce((s,r)=>s+(r.earned??Number(report.manualScores[r.id]||0)),0);return {t,max,score,pending:rr.some(r=>r.earned===null&&report.manualScores[r.id]===undefined)}}).filter(x=>x.max);
 return pageHead('YOUR LEARNING REPORT','每一次检验，都是进步的起点。',`${esc(report.title)} · ${new Date(report.finishedAt).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'})}`)+`
 <section class="report-hero"><div class="score-ring" style="--progress:${pct}%"><div><strong>${raw}</strong><small>/ ${total} 分</small></div></div><div><h2>${pending.length?'客观题已批改，部分题目待评阅。':pct>=80?'基础扎实，继续保持。':pct>=60?'继续巩固，向更稳的掌握前进。':'找准薄弱点，再练一组。'}</h2><p>自动判分全对 ${correct} / ${report.results.filter(r=>r.earned!==null).length} 题 · 用时 ${Math.floor(report.seconds/60)}分${report.seconds%60}秒${pending.length?` · 另有 ${pendingMax}分待评阅`:` · 得分率 ${pct}%`}</p><div class="button-row">${btn('错题再练','retry-report','','primary')}${btn('下载得分报告','download-report')}${btn('返回学习中心','nav','data-page="home"')}</div></div></section>
 ${pending.length?'<div class="callout">当前分数未包含待评阅部分。请根据题目参考答案与评分点，由教师评阅或自行核对后录入得分；系统不会把开放问答伪装为自动评分。</div>':''}
 <div class="grid-2"><section class="panel"><h2>知识点得分</h2>${topicStats.map(x=>`<div class="topic-row"><span>${x.t}<small>${x.score} / ${x.max}分${x.pending?' · 待评阅':''}</small></span><div class="track"><i style="width:${x.score/x.max*100}%"></i></div></div>`).join('')}</section><section class="panel"><h2>下一步怎么练</h2><p class="sub">${topicStats.filter(x=>!x.pending&&x.score<x.max).length?'建议从以下考点开始专项复习：':'可以继续完成其他原卷，保持稳定的作答节奏。'}</p><div class="chips" style="margin:18px 0">${topicStats.filter(x=>!x.pending&&x.score<x.max).sort((a,b)=>a.score/a.max-b.score/b.max).slice(0,3).map(x=>`<button class="chip" data-act="topic" data-topic="${x.t}">${x.t} ${icon('arrow',13)}</button>`).join('')}</div><p class="small-note">评分说明：单选、判断、填空按题分；多选默认全对得分，仅原卷注明少选规则时给部分分。综合题分支在开考前选定。报告是练习参考，不代替官方成绩或合格认定。</p></section></div>
 <div class="review-head"><h2>逐题回顾</h2><span class="small-note">点击一道题，查看作答与精讲</span></div><div class="panel table-wrap" style="padding:0"><table class="report-table"><thead><tr><th>题号</th><th>考点</th><th>状态</th><th>得分</th><th>回顾</th></tr></thead><tbody>${report.results.map((r,i)=>`<tr><td>${i+1} <small>原${qBy(r.id).number}</small></td><td>${qBy(r.id).topic}</td><td>${r.earned===null?(report.manualScores[r.id]!==undefined?'已录入评阅':'待人工评阅'):r.status}</td><td>${r.earned??(report.manualScores[r.id]===undefined?'—':report.manualScores[r.id])} / ${r.max}</td><td><button data-act="review" data-id="${r.id}">查看精讲</button></td></tr>`).join('')}</tbody></table></div>${reviewId?reviewHtml(reviewId):''}`;
}
function reviewHtml(id){const r=report.results.find(r=>r.id===id),q=qBy(id);return `<article class="question-card" id="review-question" style="margin-top:22px"><div class="badges">${badge(q)}<span class="badge gray">原题${q.number}</span></div>${questionBody(q,r.answer,true,true)}${analysis(q,r.answer)}${q.manual?`<div class="manual-box"><h3>${q.type==='subjective'?'按评分要点核对并录入得分':'教师复核：原题存在歧义'}</h3><p class="small-note">${esc(q.explanation)}</p><label for="manual-score">本题评阅得分（不自动判断）<select id="manual-score" data-id="${id}"><option value="">待评阅</option>${Array.from({length:q.points+1},(_,i)=>`<option value="${i}" ${String(report.manualScores[id])===String(i)?'selected':''}>${i}分</option>`).join('')}</select></label></div>`:''}</article>`}
function mistakePage(){return pageHead('LEARN FROM MISTAKES','把做错的，变成会做的。','错题只在当前浏览器标签页暂存；关闭标签页后可能清除。',wrong.length?btn('导出错题学生版','export-wrong'):'')+(wrong.length?`<div class="button-row" style="margin-bottom:20px">${btn('开始错题再练','retry-wrong','','primary')}${btn('清空临时错题','clear-wrong')}</div>${wrong.map(id=>{const q=qBy(id);return `<article class="mistake-row"><span class="tile-icon rose">${icon('flag',18)}</span><div><div class="badges"><span class="badge gray">${q.topic}</span>${badge(q)}</div><h3>${esc(q.stem.slice(0,80))}${q.stem.length>80?'…':''}</h3><span class="small-note">${sourceName(q)} · 原题${q.number}</span></div><div class="actions">${btn('再做一次','one',`data-id="${id}"`,'small')}${btn('移出错题','remove-wrong',`data-id="${id}"`,'small')}</div></article>`}).join('')}`:`<section class="empty">${icon('book',42)}<h2>这里，等待你需要巩固的题。</h2><p>完成作答后，系统会把失分题自动放进来。答对的题也可在核对后手动移出。</p>${btn('做一组真题','quick','','primary')}</section>`)}
function notesPage(){const t=noteTopic,n=DB.notes[t];return pageHead('QUICK KNOWLEDGE NOTES','知识有序，考点清晰。','从已导入试卷提炼的基础速记，配合做题理解。')+`<div class="notes-layout"><nav class="note-nav" aria-label="考点分类">${TOPICS.map(t=>`<button data-act="note" data-topic="${t}" class="${t===noteTopic?'active':''}">${t}</button>`).join('')}</nav><article class="panel note-sheet"><div class="eyebrow">KNOWLEDGE / ${String(TOPICS.indexOf(t)+1).padStart(2,'0')}</div><h2 style="font-size:26px">${t}</h2><p class="sub">${n.headline}</p>${n.items.map((item,i)=>`<div class="note-item"><b>${String(i+1).padStart(2,'0')}</b><p>${esc(item)}</p></div>`).join('')}<div class="button-row">${btn('用几道题检验掌握程度 '+icon('arrow',16),'topic',`data-topic="${t}"`,'primary')}</div><div class="callout info">范围仅限高中信息技术合格性考试基础。涉及AI与数据分析时，理解基本概念和应用场景即可，无需大学算法、模型训练或选考拓展内容。</div></article></div>`}
function filtered(){return Q.filter(q=>(filters.topic==='全部'||q.topic===filters.topic)&&(filters.type==='全部'||q.type===filters.type)&&(filters.source==='全部'||(filters.source==='true'?q.kind==='true':q.kind!=='true'))&&(!filters.search||[q.stem,q.topic,sourceName(q),q.number].join(' ').toLowerCase().includes(filters.search.toLowerCase())))}
function libraryPage(){const qs=filtered();return pageHead(page==='explain'?'TRUE QUESTIONS, CLEAR EXPLANATIONS':'QUESTION LIBRARY',page==='explain'?'先想清楚，再看精讲。':'每一道题，都有来源。',page==='explain'?'选择一道题独立作答，提交后展开固定四步解析。':'105道原卷小题 + 16道对标模拟题；按小题计数，Word与PDF同卷已去重。')+`
 <div class="searchbar"><input class="control" id="library-search" aria-label="搜索题目或知识点" placeholder="搜索题干、知识点或试卷…" value="${esc(filters.search)}"><select class="control" id="library-topic" aria-label="筛选知识点"><option>全部</option>${TOPICS.map(t=>`<option ${filters.topic===t?'selected':''}>${t}</option>`).join('')}</select><select class="control" id="library-type" aria-label="筛选题型"><option value="全部">全部题型</option>${Object.entries(typeNames).map(([v,t])=>`<option value="${v}" ${filters.type===v?'selected':''}>${t}</option>`).join('')}</select><select class="control" id="library-source" aria-label="筛选来源"><option value="全部">全部来源</option><option value="true" ${filters.source==='true'?'selected':''}>历年真题</option><option value="mock" ${filters.source==='mock'?'selected':''}>模拟题</option></select>${btn('搜索','filter')}</div>
 ${page==='library'?`<details class="panel" style="margin-bottom:20px"><summary style="cursor:pointer;font-size:13px">导入记录与原稿校核说明（3套试卷）</summary><div style="padding-top:16px">${DB.papers.map(p=>`<h3>${p.title}</h3><p class="small-note">${p.note}</p>`).join('')}<p class="small-note">已导入：2023年3月Word/PDF（合并去重）、2023年12月Word（以同目录PDF辅助核对排版）、福田区2024—2025 PDF。文件内的考试操作要求作为原卷内容保存，不作为本系统运行指令。</p><p class="small-note">题干做了标点、冗余文字与排版整理。影响作答的修订在对应题目或解析中说明。${DB.audit.answerPolicy}</p></div></details>`:''}
 <div class="section-title"><h2>找到 ${qs.length} 道题</h2><span class="small-note">答案在作答提交后可见</span></div><div class="panel">${qs.length?qs.map(q=>`<article class="library-row"><div><div class="badges">${badge(q)}<span class="badge gray">${q.topic}</span><span class="badge gray">${typeNames[q.type]}</span></div><h3>${esc(q.stem.slice(0,115))}${q.stem.length>115?'…':''}</h3><div class="small-note">${sourceName(q)} · 原题 ${q.number}${q.manual?' · 需人工评阅':''}</div></div>${btn('作答精讲','one',`data-id="${q.id}"`,'small')}</article>`).join(''):'<p class="sub">没有符合条件的题目，试试其他关键词。</p>'}</div>`}
function exportPage(){return pageHead('BUILD YOUR OWN PAPER','一份试卷，两种用途。','按知识点与题型随机组卷，导出可打印HTML、Markdown，或打印为PDF。')+`
 <form id="export-form" class="panel config"><div class="grid-2"><div class="field"><label for="export-title">试卷标题</label><input id="export-title" value="${esc(exportTitle)}" maxlength="80" required></div><div class="field"><label for="export-topic">知识范围</label><select id="export-topic"><option>全部</option>${TOPICS.map(t=>`<option>${t}</option>`).join('')}</select></div><div class="field"><label for="export-type">题型</label><select id="export-type"><option value="全部">全部题型</option>${Object.entries(typeNames).filter(([v])=>v!=='subjective').map(([v,t])=>`<option value="${v}">${t}</option>`).join('')}</select></div><div class="field"><label for="export-count">小题数量</label><input type="number" id="export-count" min="1" max="100" value="10" required></div><div class="field"><label for="export-source">题目来源</label><select id="export-source"><option value="priority">真题优先</option><option value="true">只选真题</option><option value="mock">模拟题</option><option value="all">全部随机混合</option></select></div><div class="field"><label for="export-version">预览与导出版本</label><select id="export-version"><option value="student" ${!exportTeacher?'selected':''}>学生版 · 仅题目与作答区</option><option value="teacher" ${exportTeacher?'selected':''}>教师版 · 题目、答案与完整解析</option></select></div></div><button class="button primary" type="submit">生成试卷 ${icon('export',16)}</button><p class="small-note" style="margin:12px 0 0">候选题不足时导出实际题量；综合题小题会带上所需情境、程序和图示。不会用重复题凑数。</p></form>
 ${exportSet.length?`<section class="export-preview"><div class="print-actions">${btn('下载'+(exportTeacher?'教师版':'学生版')+' HTML','download-html','','primary')}${btn('下载 Markdown','download-md')}${btn('打印 / 另存为 PDF','print')}${btn('切换为'+(exportTeacher?'学生版':'教师版'),'toggle-version')}</div><div id="print-paper">${paperHtml(exportSet,exportTeacher,exportTitle)}</div></section>`:''}`}
function paperHtml(qs,teacher,title){return `<h1>${esc(title)}</h1><p class="sub">${teacher?'教师版 · 含参考答案与解析':'学生版 · 姓名：____________　班级：____________'}<br>共${qs.length}道小题，满分${qs.reduce((s,q)=>s+q.points,0)}分</p>${teacher?'<p class="small-note">答案来源：3月卷使用原稿标注，其他为助教参考答案；原稿问题见题目说明。开放题需人工评阅。</p>':''}${qs.map((q,i)=>`<article class="export-q"><div class="badges">${badge(q)}<span class="badge gray">${sourceName(q)} · ${q.number}</span></div><h3>${i+1}.（${q.points}分）${esc(q.stem)}</h3>${q.context?`<p style="font-size:12px">${esc(q.context)}</p>`:''}${q.code?`<pre class="code">${esc(q.code)}</pre>`:''}${q.image?`<img class="question-image" src="${q.imageData||new URL(q.image,location.href).href}" alt="题目图示">`:''}${q.diagram?diagram():''}<div class="print-options">${q.options.map((v,j)=>esc(String.fromCharCode(65+j)+'. '+v)).join('\n')}</div><p style="font-size:12px;margin:20px 0">作答：____________________________________________________</p>${teacher?`<div class="analysis"><dl><dt>答案</dt><dd>${esc(correctLabel(q))}</dd><dt>考点</dt><dd>${q.topic}</dd><dt>解析</dt><dd>${esc(q.explanation)}</dd><dt>易错提醒</dt><dd>${esc(q.pitfall)}</dd></dl></div>`:''}</article>`).join('')}`}
function paperMarkdown(qs,teacher,title){return `# ${title}\n\n${teacher?'教师版 · 含助教参考答案':'学生版 · 姓名：________　班级：________'}\n\n共${qs.length}题，满分${qs.reduce((s,q)=>s+q.points,0)}分。\n\n`+qs.map((q,i)=>`## ${i+1}. ${q.stem}（${q.points}分）\n\n${sourceText(q)} ${sourceName(q)} 原题${q.number}\n\n${q.context?q.context+'\n\n':''}${q.code?'```python\n'+q.code+'\n```\n\n':''}${q.image?'![题目图示]('+(q.imageData||new URL(q.image,location.href).href)+')\n\n':''}${q.diagram?'流程：开始→输入x→判断x>0→是：输出正数；否：输出非正数→结束。\n\n':''}${q.options.map((v,j)=>String.fromCharCode(65+j)+'. '+v.replace(/\n/g,'\n   ')).join('\n\n')}\n\n作答：________________\n\n${teacher?`**答案**：${correctLabel(q)}\n\n**考点**：${q.topic}\n\n**解析**：${q.explanation}\n\n**易错提醒**：${q.pitfall}\n\n`:''}`).join('---\n\n')}
function download(name,text,type='text/plain;charset=utf-8'){const u=URL.createObjectURL(new Blob(['\ufeff',text],{type})),a=document.createElement('a');a.href=u;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),2000);toast('文件已生成，请查看浏览器下载。')}
function help(){modal('欢迎来到知序',`<p><strong>你好，高中信息技术学考题库系统已就绪✅</strong><br>支持：随机刷题｜专项刷题｜全真模考｜错题本｜真题精讲｜考点速记｜组卷导出。</p><ul><li>刷题：选答案后提交，只展开当前题解析。</li><li>模考：60分钟，综合题二选一，点击“交卷”统一评分。</li><li>错题：暂存在本标签页，可再练、移出和导出。</li><li>组卷：学生版不含答案，教师版含固定四步解析。</li><li>学习统计保存在当前浏览器本机，不跨设备同步。完整作答和错题使用本标签页临时存储。</li></ul><p>界面应用 <a href="https://github.com/nextlevelbuilder/ui-ux-pro-max-skill" target="_blank" rel="noopener">UI UX Pro Max</a> 的简洁布局与无障碍规范；网站由 Sites 技能创建。</p>${btn('开始学习','close','','primary')}`)}
document.addEventListener('click',e=>{
 const b=e.target.closest('[data-act]');if(!b||b.disabled)return;const {act}=b.dataset;
 if(act==='nav')go(b.dataset.page);
 else if(act==='skip'){$('#main').focus();$('#main').scrollIntoView()}else if(act==='close')close();else if(act==='resume'){close();go('practice')}
 else if(act==='replace-session'){close();pendingStart?.();pendingStart=null}
 else if(act==='quick')beginSession(selectQuestions({count:10}),'practice','真题优先 · 随机练习');
 else if(act==='topic'){noteTopic=b.dataset.topic;go('random');$('#main').innerHTML=pageHead('TOPIC PRACTICE',b.dataset.topic+' · 专项练习','选择题型与题量，逐个掌握这个考点。')+configHtml(b.dataset.topic)}
 else if(act==='note'){noteTopic=b.dataset.topic;render()}
 else if(act==='start-exam'){const p=b.dataset.paper,g=$('#group-'+p).value;beginSession(makeExam(p,g),'exam',paper(p).title+' · '+(g==='26'?'综合题一':'综合题二'))}
 else if(act==='answer'){
  const q=currentQ();if(!q||session.finished||session.mode==='exam'&&Date.now()>=session.deadline||session.mode!=='exam'&&session.graded[q.id])return;
  if(q.type==='multi'){const a=session.answers[q.id]||[];session.answers[q.id]=a.includes(b.dataset.value)?a.filter(v=>v!==b.dataset.value):[...a,b.dataset.value].sort()}else session.answers[q.id]=b.dataset.value;
  saveSession();render();
 }else if(act==='grade'){
  const q=currentQ();if(!answered(session.answers[q.id]))return;if(session.graded[q.id])return;session.graded[q.id]=true;record(q,session.answers[q.id]);saveSession();render();$('#analysis')?.scrollIntoView({block:'nearest',behavior:'smooth'});
 }else if(act==='next'){
  if(session.mode!=='exam'&&!session.graded[currentQ().id])return;
  if(session.index<session.ids.length-1){session.index++;saveSession();render();window.scrollTo(0,0)}else finish();
 }else if(act==='prev'){session.index=Math.max(0,session.index-1);saveSession();render()}
 else if(act==='jump'){const idx=Number(b.dataset.index);if(session.mode==='exam'||idx<=session.index||session.graded[session.ids[idx-1]]){session.index=idx;saveSession();render();window.scrollTo(0,0)}}
 else if(act==='flag'){const id=currentQ().id;session.flags=session.flags.includes(id)?session.flags.filter(x=>x!==id):[...session.flags,id];saveSession();render()}
 else if(act==='submit-exam')submitExam();else if(act==='confirm-exam'){close();finish()}
 else if(act==='one')beginSession([qBy(b.dataset.id)],'practice','逐题精讲');
 else if(act==='retry-wrong')beginSession(shuffle(wrong.map(qBy)).filter(q=>!q.manual),'practice','错题巩固');
 else if(act==='retry-report')beginSession(report.results.filter(r=>r.earned!==null&&r.earned<r.max).map(r=>qBy(r.id)),'practice','本次失分题再练');
 else if(act==='remove-wrong'){wrong=wrong.filter(id=>id!==b.dataset.id);write(sessionStorage,'zhixu-wrong',wrong);render()}
 else if(act==='clear-wrong')modal('清空临时错题本',`<p>将移除当前标签页的 ${wrong.length} 道错题记录。学习统计仍保留。</p><div class="button-row">${btn('保留错题','close')}${btn('确认清空','confirm-clear','','danger')}</div>`);
 else if(act==='confirm-clear'){wrong=[];write(sessionStorage,'zhixu-wrong',wrong);close();render()}
 else if(act==='review'){reviewId=b.dataset.id;render();$('#review-question').scrollIntoView({behavior:'smooth',block:'start'})}
 else if(act==='filter'){filters={topic:$('#library-topic').value,type:$('#library-type').value,source:$('#library-source').value,search:$('#library-search').value.trim()};render()}
 else if(act==='toggle-version'){exportTeacher=!exportTeacher;render()}
 else if(act==='export-wrong'){exportSet=wrong.map(qBy);exportTitle='信息技术学考 · 错题巩固卷';exportTeacher=false;go('export')}
 else if(act==='download-md')download(exportTitle+(exportTeacher?'教师版':'学生版')+'.md',paperMarkdown(exportSet,exportTeacher,exportTitle),'text/markdown;charset=utf-8');
 else if(act==='download-html'){
  const css='body{font-family:"Microsoft YaHei",sans-serif;max-width:850px;margin:40px auto;padding:0 22px;line-height:1.8;color:#213a34}h1{text-align:center;font-size:25px}.sub{text-align:center}.export-q{border-top:1px solid #ddd;padding:24px 0;break-inside:avoid}h3{font-size:16px}.badge{font-size:11px;color:#176d5b;margin-right:12px}.code{white-space:pre-wrap;background:#f4f6f2;padding:18px;font:13px/1.8 Consolas,monospace}.print-options{white-space:pre-wrap;font-size:14px}.question-image{display:block;max-width:100%;max-height:350px;margin:20px auto}.analysis{border:1px solid #ccc;padding:18px;margin:20px 0}.analysis dl{display:grid;grid-template-columns:75px 1fr;gap:10px;font-size:13px}.analysis dt{font-weight:bold}.analysis dd{margin:0;white-space:pre-wrap}.small-note{font-size:12px;color:#555}.flowchart{border:1px solid #aaa;padding:15px;text-align:center}.node{display:block}.branch{margin:12px}.diamond{margin:15px}@page{size:A4;margin:18mm}@media print{body{margin:0;max-width:none;padding:0}}';
  download(exportTitle+(exportTeacher?'教师版':'学生版')+'.html',`<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(exportTitle)}</title><style>${css}</style><body>${paperHtml(exportSet,exportTeacher,exportTitle)}</body></html>`,'text/html;charset=utf-8');
 }else if(act==='print')window.print();
 else if(act==='download-report'){
  const max=report.results.reduce((s,r)=>s+r.max,0),earned=report.results.reduce((s,r)=>s+(r.earned??Number(report.manualScores[r.id]||0)),0),pending=report.results.filter(r=>r.earned===null&&report.manualScores[r.id]===undefined).reduce((s,r)=>s+r.max,0);
  download('知序-得分报告.md',`# ${report.title} · 得分报告\n\n当前得分：${earned}/${max}分${pending?'，另有'+pending+'分待人工评阅':''}。\n\n|题号|考点|你的作答|得分|\n|---|---|---|---|\n`+report.results.map((r,i)=>`|${i+1}（原${qBy(r.id).number}）|${qBy(r.id).topic}|${String(answerLabel(qBy(r.id),r.answer)).replace(/\|/g,'／').replace(/\n/g,' ')}|${r.earned??(report.manualScores[r.id]??'待评阅')}/${r.max}|`).join('\n')+'\n\n助教参考评分；不代替官方成绩或合格认定。');
 }
});
document.addEventListener('input',e=>{
 if(e.target.id==='answer-input'&&session&&!session.finished){const q=currentQ();if(session.mode==='exam'&&Date.now()>=session.deadline)return;session.answers[q.id]=e.target.value;saveSession();const b=$('[data-act="grade"]');if(b)b.disabled=!answered(e.target.value)}
});
document.addEventListener('change',e=>{if(e.target.id==='manual-score'){if(e.target.value==='')delete report.manualScores[e.target.dataset.id];else report.manualScores[e.target.dataset.id]=Number(e.target.value);write(sessionStorage,'zhixu-report',report);const y=window.scrollY;render();window.scrollTo(0,y);toast('评阅得分已保存，报告已更新。')}});
document.addEventListener('submit',e=>{
 e.preventDefault();if(e.target.id==='practice-form'){const f=new FormData(e.target),opts={topic:f.get('topic'),type:f.get('type'),source:f.get('source'),count:Number(f.get('count'))};const qs=selectQuestions(opts);if(qs.length<opts.count)toast('当前条件仅有'+qs.length+'道可练题，按实际题量开始。');beginSession(qs,'practice',opts.topic==='全部'?'真题优先 · 随机练习':opts.topic+' · 专项练习')}
 if(e.target.id==='export-form'){exportTitle=$('#export-title').value.trim()||'信息技术学考练习卷';exportTeacher=$('#export-version').value==='teacher';const count=Math.min(100,Math.max(1,Number($('#export-count').value)));exportSet=selectQuestions({topic:$('#export-topic').value,type:$('#export-type').value,source:$('#export-source').value,count});render();if(exportSet.length){$('.export-preview').scrollIntoView({behavior:'smooth'});toast(`已生成 ${exportSet.length} 道小题${exportSet.length<count?'，候选题不足，按实际题量生成':''}。`)}else toast('当前条件没有可用题目，请调整筛选。')}
});
document.addEventListener('keydown',e=>{
 if(e.key==='Escape')$('#sidebar').classList.remove('open');
 if(e.target.id==='library-search'&&e.key==='Enter'){e.preventDefault();$('[data-act="filter"]').click()}
 if(page!=='practice'||!session||session.finished||$('#modal').open||['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName)||e.ctrlKey||e.metaKey||e.altKey)return;
 const c=e.key.toUpperCase();if(/^[A-D]$/.test(c)){const b=$(`[data-act="answer"][data-value="${c}"]`);b?.click()}
});
$('#menu-toggle').addEventListener('click',()=>$('#sidebar').classList.toggle('open'));$('#help').addEventListener('click',help);
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)close()}});
window.addEventListener('hashchange',()=>{const next=location.hash.slice(1)||'home';if(next==='main'){$('#main').focus();return}if(next!==page){page=next;render();window.scrollTo(0,0)}});
window.XuekaoCore={evaluate,selectQuestions,makeExam,paperMarkdown,paperHtml,questions:Q};
render();
})();
